import {project,unproject,makeArea,POLICY,energy,fare,distance} from './engine.js';
import {loadBoundary,loadRoads,loadStations,cacheGet,hashJSON} from './data.js';
import {exampleData} from './example.js';
import {zipFiles} from './zip.js';
const $=id=>document.getElementById(id), svgNS='http://www.w3.org/2000/svg';
const places=[['Columbus Circle',[-73.9819,40.7681]],['5 Ave · E 59 St',[-73.9731,40.7646]],['Central Park W · W 72 St',[-73.9784,40.7763]],['5 Ave · E 72 St',[-73.9664,40.7711]],['Central Park W · W 96 St',[-73.9646,40.7918]],['5 Ave · E 96 St',[-73.9539,40.7878]],['Frederick Douglass Circle',[-73.9582,40.8005]],['Duke Ellington Circle',[-73.9492,40.7967]],['직접 지정',null]];
const placeholder={type:'Polygon',coordinates:[[[-73.9819,40.7681],[-73.973,40.7644],[-73.9491,40.7968],[-73.9582,40.8005],[-73.9819,40.7681]]]};
let area=makeArea(placeholder),raw=null,roads=[],stations=[],stateData=null,worker=null,built=false,demo=false,imported=false,epoch=0,requestID=0,result=null,selected='A',metric='kcal',playing=false,playAt=0,sequence=[],current=null,view=null,baseView=null,routeTimer=null,stationTimer=null,loading=false;
let A=project(places[0][1]),B=project(places[7][1]);
const money=c=>'$'+(c/100).toFixed(2),km=m=>(m/1000).toFixed(2),mins=s=>(s/60).toFixed(1),clock=s=>String(Math.floor(s/60)).padStart(2,'0')+':'+String(Math.floor(s%60)).padStart(2,'0');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function el(tag,attrs={},text){const e=document.createElementNS(svgNS,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;return e;}
function xy(p){return [p[0]-area.bounds[0],area.bounds[3]-p[1]];}function world(p){return [p[0]+area.bounds[0],area.bounds[3]-p[1]];}
function path(points,close=false){return points.map((p,i)=>{const q=xy(p);return (i?'L':'M')+q[0].toFixed(1)+','+q[1].toFixed(1);}).join(' ')+(close?' Z':'');}
function setView(){if(view)$('map').setAttribute('viewBox',view.join(' '));}function fit(){view=[0,0,area.bounds[2]-area.bounds[0],area.bounds[3]-area.bounds[1]];baseView=[...view];setView();}
function textAt(p,text,size=65,cls=''){const q=xy(p);return el('text',{x:q[0],y:q[1],'text-anchor':'middle','font-size':size,class:'map-label '+cls},text);}
function drawBase(){fit();const base=$('mapBase');base.replaceChildren();const w=view[2],h=view[3];base.append(el('rect',{width:w,height:h,fill:'#eef1e8'}),el('rect',{width:w,height:h,fill:'url(#grid)'}));for(const poly of area.polygons){const d=poly.map(r=>path(r,true)).join(' ');base.append(el('path',{d,fill:'#e1e9d7',stroke:'#e1e9d7','stroke-width':2000,'stroke-linejoin':'round','fill-rule':'evenodd'}));}
 // OSM ways share actual OSM nodes. No generated street grid is used for real data.

 for(const poly of area.polygons)base.append(el('path',{d:poly.map(r=>path(r,true)).join(' '),fill:'#ccddba',stroke:'#aac496','stroke-width':8,'fill-rule':'evenodd'}));
 if(raw){const nodes=new Map(raw.elements.filter(x=>x.type==='node').map(n=>[n.id,project([n.lon,n.lat])]));for(const r of raw.elements.filter(x=>x.type==='way'&&x.tags?.natural==='water')){const pts=r.nodes.map(n=>nodes.get(n)).filter(Boolean);if(pts.length>2)base.append(el('path',{d:path(pts,true),fill:'#b9d3ca',stroke:'#9cbdb3','stroke-width':3}));}}
 const ordinary=roads.filter(r=>!r.drive),drives=roads.filter(r=>r.drive);for(const list of [ordinary,drives])for(const r of list){const d=r.segments.map(s=>path(s)).join(' ');const foot=['footway','path','steps','pedestrian'].includes(r.type);base.append(el('path',{d,fill:'none',stroke:r.drive?'#f8faf3':foot?'#b6cba2':'#fafbf6','stroke-width':r.drive?26:foot?5:22,'stroke-linecap':'round'}));if(!foot&&!r.drive)base.append(el('path',{d,fill:'none',stroke:'#d7ddcf','stroke-width':2}));}
 base.append(textAt(project([-73.9653,40.7829]),'CENTRAL',78,'park'),textAt(project([-73.9648,40.7818]),'PARK',78,'park'),textAt(project([-73.988,40.785]),'UPPER WEST SIDE',48),textAt(project([-73.9475,40.778]),'UPPER EAST SIDE',48));
 for(const p of places.slice(0,-1)){const q=project(p[1]);if(area.contains(q))base.append(textAt(q,p[0],31));}drawMarkers();drawStations();}
function drawMarkers(){const g=$('mapMarkers');g.replaceChildren();for(const [name,p]of [['A',A],['B',B]]){const q=xy(p),group=el('g',{transform:`translate(${q})`,class:'marker','data-point':name,tabindex:0,role:'button','aria-label':name+' 지점. 방향키로 이동'});group.append(el('circle',{r:66,fill:'#ffffff',opacity:.7}),el('circle',{r:46,fill:name==='A'?'#244f40':'#d5ee9b',stroke:'#fff','stroke-width':8}),el('text',{'text-anchor':'middle',y:15,'font-size':40,'font-weight':600,fill:name==='A'?'white':'#244f40'},name));g.append(group);}}
function drawStations(){const g=$('mapStations');g.replaceChildren();for(const s of stations){const q=xy(s.p),isSelected=current&&(current.start?.id===s.id||current.end?.id===s.id),c=el('circle',{cx:q[0],cy:q[1],r:isSelected?30:13,fill:s.ebikes>0?'#fff':'#cbd1c2',stroke:'#618251','stroke-width':isSelected?9:5,class:'station-dot','data-station':s.id});const title=el('title',{},`${s.name}\n전기자전거 ${s.ebikes??'미확인'} · 도크 ${s.docks??'미확인'}\n${s.battery==='unknown'?'배터리 잔량 미확인':''}`);c.append(title);g.append(c);}}
function choosePoint(name,p){if(!area.contains(p)){showError('OUTSIDE_AREA');return;}if(name==='A')A=p;else B=p;$('place'+name).value=String(places.length-1);updateCoords();drawMarkers();schedule();}
function updateCoords(){for(const [name,p]of [['A',A],['B',B]])$('coord'+name).value=unproject(p).map(n=>n.toFixed(6)).join(', ');}
function settings(){const get=(id,min,max)=>{const n=Number($(id).value);if(!Number.isFinite(n)||n<min||n>max)throw new Error('INVALID_SETTINGS');return n;};return {mass:get('mass',20,250),speed:get('speed',5,24.14),met:get('met',3,6),walkLimit:get('walkLimit',100,2000),pause:get('pause',0,120),profile:$('profile').value,newPass:$('newPass').checked};}
const errors={OUTSIDE_AREA:'A와 B는 센트럴파크와 경계 바깥 1km 안에 지정해 주세요.',SNAP_TOO_FAR:'50m 이내에 연결 가능한 도로가 없습니다. 지도에서 도로나 공원 입구 가까이 지점을 옮겨 주세요.',NO_EBIKE_OR_WALK_ACCESS:'도보 한도 안에 대여 가능한 전기자전거 정류장이 없습니다. A를 옮기거나 도보 한도를 늘려 보세요.',NO_DOCK_OR_WALK_ACCESS:'도보 한도 안에 반납 가능한 정류장이 없습니다. B를 옮기거나 도보 한도를 늘려 보세요.',NO_ROUTE_WITHIN_STUDY_AREA:'대상 범위 안에서 연결되는 경로가 없습니다. 공원 내 승차 금지·일방통행을 우회할 연결이 필요합니다.',INVALID_COORDINATE:'경도, 위도를 숫자로 입력해 주세요.',INVALID_SETTINGS:'설정값이 허용 범위를 벗어났습니다.',STALE_FEED:'정류장 상태가 5분 이상 지났습니다. 새로고침 후 다시 계산해 주세요.'};
function showError(code){$('error').hidden=false;$('error').textContent=errors[code]??code;}
function clearResult(){result=null;current=null;playing=false;playAt=0;sequence=[];$('play').disabled=true;$('scrubber').disabled=true;$('export').disabled=true;$('mapRoutes').replaceChildren();$('mapTraveler').replaceChildren();for(const id of ['kcal','usd'])$(id).textContent='—';$('length').textContent='— km';$('duration').textContent='— 분';$('legLength').textContent='— / — km';$('rental').textContent='— / — 분';$('stationDetail').textContent='경로 계산 후 출발·반납 정류장을 표시합니다.';$('warnings').textContent='';$('comparison').textContent='거리 최단·시간 최단 후보의 요금을 비교합니다.';$('kcalRange').textContent='체중과 이동시간에 따라 달라집니다';$('fareDetail').textContent='전기자전거는 첫 분부터 과금';$('play').textContent='▶ 재생';drawChart();}
function schedule(){clearTimeout(routeTimer);requestID++;clearResult();if(built){$('calculate').disabled=false;routeTimer=setTimeout(calculate,300);}}
function calculate(){if(!built)return;let opt;try{opt=settings();}catch(e){showError(e.message);return;}if(demo)for(const s of stations)s.timestamp=Date.now()/1000;if(imported){const max=Math.max(...stations.map(s=>s.recorded_timestamp??s.timestamp).filter(Number.isFinite));for(const s of stations)s.timestamp=Date.now()/1000-(max-(s.recorded_timestamp??s.timestamp));}if(!demo&&!imported&&stations.every(s=>Date.now()/1000-s.timestamp>300)){clearResult();showError('STALE_FEED');return;}clearResult();$('error').hidden=true;$('calculate').disabled=true;$('calculate').firstElementChild.textContent='경로 탐색 중…';const id=++requestID;worker.postMessage({type:'route',id,a:A,b:B,stations,settings:opt});}
function setupWorker(data){worker?.terminate();worker=new Worker('./worker.js',{type:'module'});built=false;worker.onerror=e=>{showError('계산 모듈을 불러오지 못했습니다. HTTP 서버로 실행해 주세요.');$('calculate').disabled=true;};worker.onmessage=({data:r})=>{if(r.type==='built'){built=true;roads=r.roads;drawBase();$('loading').value=3;$('loading').hidden=true;$('calculate').disabled=false;$('calculate').firstElementChild.textContent='경로 계산하기';if(demo){$('dataStatus').textContent=`예제 네트워크 · ${r.stats.nodes.toLocaleString()}개 노드 · 실제 길안내 불가`;}else{const stale=stations.some(s=>Date.now()/1000-s.timestamp>120);$('dataStatus').textContent=`${r.stats.nodes.toLocaleString()}개 도로 노드 · ${stations.length}개 정류장\n${stale?'일부 상태가 2분 이상 지났습니다.':'정류장 상태 연결됨'} · 배터리 잔량 미확인`;}if(imported)$('dataStatus').textContent+=' · 저장된 시나리오';$('mapMessage').hidden=true;calculate();}if(r.type==='route'&&r.id===requestID){result=r.result;current=result.shortest;renderResult();$('calculate').disabled=false;$('calculate').firstElementChild.textContent='경로 다시 계산하기';}if(r.type==='error'&&r.id===requestID){showError(r.message);$('calculate').disabled=false;$('calculate').firstElementChild.textContent='경로 다시 계산하기';}};worker.postMessage({type:'build',raw:data.raw,geometry:data.geometry});}
async function connect(force=false,alternate=false){const token=++epoch;clearInterval(stationTimer);clearResult();built=false;demo=false;imported=false;loading=true;$('calculate').disabled=true;$('retry').disabled=true;$('loading').hidden=false;$('loading').value=0;$('modeBadge').classList.remove('demo');$('modeBadge').innerHTML='<i></i> 실제 데이터 연결 중';$('dataStatus').textContent='1/3 · NYC Parks 공식 경계를 읽고 있습니다.';$('mapMessage').hidden=false;$('mapMessage').textContent='공식 지도 데이터를 불러오고 있습니다.';try{const park=await loadBoundary();if(token!==epoch)return;area=makeArea(park.feature.geometry);drawBase();$('loading').value=1;$('dataStatus').textContent='2/3 · 도로 네트워크와 정류장 연결 중 (최초 1–2분)';const [roadData,stationData]=await Promise.all([loadRoads(area,force,alternate?1:0),loadStations(area)]);if(token!==epoch)return;raw=roadData.raw;stations=stationData.stations;stateData={geometry:park.feature.geometry,raw,stations,manifest:{boundary:{url:park.source,fetched:park.fetched},osm:{url:roadData.source,timestamp:roadData.timestamp,fetched:roadData.fetched,outdated:roadData.outdated??false},gbfs:{fetched:stationData.fetched,timestamp:stationData.source_timestamp,version:stationData.version},projection:'EPSG:32618',policy:POLICY.id,mode:'live'}};$('modeBadge').innerHTML='<i></i> '+(roadData.outdated?'오래된 도로 캐시':'실제 데이터 · 조회 시점 상태');$('mapSource').textContent='© OSM contributors · NYC Parks · Citi Bike GBFS';$('dataStatus').textContent='3/3 · 방향·통행 제한을 적용해 그래프를 만드는 중';setupWorker(stateData);stationTimer=setInterval(()=>refreshStations(false),stationData.ttl*1000);}catch(error){if(token!==epoch)return;$('dataStatus').textContent='연결 실패: '+error.message+' · 다른 서버로 다시 연결하거나 예제를 선택해 주세요.';$('modeBadge').innerHTML='<i></i> 실제 데이터 연결 안 됨';$('loading').hidden=true;$('mapMessage').textContent='실제 데이터가 연결되지 않았습니다. 왼쪽에서 다시 연결하거나 예제로 기능을 살펴보세요.';$('mapSource').textContent='데이터 연결 전 · 위치 개략도';}finally{if(token===epoch){loading=false;$('retry').disabled=false;}}}
async function refreshStations(recalculate=true){if(demo||imported){if(recalculate)calculate();return;}if(!built)return;try{const data=await loadStations(area);stations=data.stations;stateData.stations=stations;stateData.manifest.gbfs={fetched:data.fetched,timestamp:data.source_timestamp,version:data.version};drawStations();$('dataStatus').textContent=`정류장 ${stations.length}개 · ${new Date(data.fetched).toLocaleTimeString('ko-KR',{timeZone:'America/New_York'})} 뉴욕 시각 갱신 · 배터리 미확인`;if(recalculate)calculate();}catch(error){$('dataStatus').textContent='정류장 갱신 실패 · 기존 시각 유지 · '+error.message;if(recalculate)showError('정류장 정보를 새로 확인하지 못했습니다. 잠시 후 다시 시도해 주세요.');}}
function useExample(){epoch++;clearInterval(stationTimer);const d=exampleData();demo=true;imported=false;loading=false;$('retry').disabled=false;raw=d.raw;stations=d.stations;A=d.a;B=d.b;area=makeArea(d.geometry);stateData={...d,manifest:{mode:'synthetic-example',projection:'EPSG:32618',policy:POLICY.id,created:new Date().toISOString()}};$('modeBadge').classList.add('demo');$('modeBadge').innerHTML='<i></i> 예제 데이터 · 실제 길안내 불가';$('mapSource').textContent='기능 확인용 합성 네트워크 · 실제 도로/역 아님';$('placeA').value=String(places.length-1);$('placeB').value=String(places.length-1);updateCoords();clearResult();setupWorker(stateData);}
function renderResult(){const j=current;if(!j)return;$('error').hidden=true;$('kcal').textContent=Math.round(j.kcal);$('usd').textContent=(j.fare.total/100).toFixed(2);$('kcalRange').textContent=`추정 범위 ${Math.round(j.low)}–${Math.round(j.high)} kcal · 활동량 ${Math.round(j.active)} kcal`;$('fareDetail').textContent=`잠금 ${money(j.fare.unlock)} + 주행 ${money(j.fare.ride)}${j.fare.pass?' + 패스 '+money(j.fare.pass):''}`;$('length').textContent=km(j.length)+' km';$('duration').textContent=mins(j.totalSeconds)+' 분';$('legLength').textContent=km(j.walkLength)+' / '+km(j.rideLength)+' km';$('rental').textContent=mins(j.rental)+' / '+j.fare.minutes+' 분';$('stationDetail').textContent=j.start?`S · ${j.start.name} (전기자전거 ${j.start.ebikes??'?'}대)\nT · ${j.end.name} (도크 ${j.end.docks??'?'}개)`:'A와 B가 같습니다. 대여 없이 이동거리 0입니다.';$('stationDetail').style.whiteSpace='pre-line';const notes=[];if(demo)notes.push('예제는 합성 도로·가상 정류장입니다.');if(imported)notes.push('저장된 스냅샷 시나리오입니다. 현재 상태가 아닙니다.');if(j.fare.warnings.length)notes.push('기준시간 초과: 장시간 과금 규칙 미확정 · 기본 단가 추정');notes.push('세금·할인 제외 · 도착 시 도크/배터리 보장 없음');if(j.legs?.some(l=>l.snapStart?.distance>2||l.snapEnd?.distance>2))notes.push('표시 거리는 50m 이내 도로 투영 지점 기준이며, 투영 연결의 보행 가능성은 별도 확인이 필요합니다.');$('warnings').textContent=notes.join(' ');if(result.cheapest){const c=result.cheapest,delta=j.fare.total-c.fare.total;$('comparison').textContent=`${result.candidates}개 정류장 쌍의 거리·시간 최단 후보 비교: ${money(c.fare.total)} · ${km(c.length)} km · ${delta>0?money(delta)+' 절약':'동일 요금'}. 전역 최저요금의 거리 동률해소는 보장하지 않습니다.`;}drawRoutes();drawStations();sequence=makeSequence(j);playAt=0;playing=false;$('play').textContent='▶ 재생';$('play').disabled=j.totalSeconds===0;$('scrubber').disabled=j.totalSeconds===0;$('export').disabled=false;drawChart();updatePlayback();$('provenance').textContent=stateData?JSON.stringify(stateData.manifest,null,2):'';}
function drawRoutes(){const g=$('mapRoutes');g.replaceChildren();if(!current)return;const draw=(j,alternative)=>{for(const leg of j.legs){if(!leg.points?.length)continue;const color=alternative?'#9b9bb1':leg.mode==='walk'?'#dc9260':metric==='kcal'?'#426b4d':'#a77b49';g.append(el('path',{d:path(leg.points),class:'route-line '+(leg.mode==='walk'?'walk':''),stroke:'#fff','stroke-width':alternative?22:36,opacity:alternative?.7:1}));g.append(el('path',{d:path(leg.points),class:'route-line '+(leg.mode==='walk'?'walk':''),stroke:color,'stroke-width':alternative?12:23,opacity:alternative?.65:1}));if(leg.mode==='ride'&&!alternative){const pts=leg.points;for(let i=3;i<pts.length;i+=Math.max(5,Math.floor(pts.length/12)))g.append(el('path',{d:path([pts[i-1],pts[i]]),stroke:color,'stroke-width':1,'marker-mid':'url(#arrow)','marker-end':'url(#arrow)'}));}}};if($('compare').checked&&result.cheapest)draw(result.cheapest,true);draw(current,false);}
function makeSequence(j){const list=[];let time=0,kcal=0;const add=(duration,met,p0,p1,rental=false)=>{if(duration<1e-7)return;const k=energy(duration/60,j.settings?.mass??70,met).gross;list.push({start:time,end:time+duration,k0:kcal,k1:kcal+k,p0,p1,rental});time+=duration;kcal+=k;};for(let n=0;n<j.legs.length;n++){const l=j.legs[n];if(l.mode==='ride')add(30,1.3,l.points[0],l.points[0],true);for(let i=0;i<l.path.length;i++){const edge=l.path[i],p0=l.points[i],p1=l.points[i+1];const speed=l.mode==='walk'?4.8:Math.min(edge.speed,j.settings.speed,24.14);add(edge.length/(speed/3.6),l.mode==='walk'?3.5:j.settings.met,p0,p1,l.mode==='ride');if(l.mode==='ride'&&edge.delay&&i<l.path.length-1)add(edge.delay,1.3,p1,p1,true);}if(l.mode==='ride'){const allotted=l.seconds+60+j.settings.pause*60;const actual=list.filter(s=>s.rental).reduce((v,s)=>v+s.end-s.start,0);add(Math.max(0,allotted-actual),1.3,l.points.at(-1),l.points.at(-1),true);}}return list;}
function valueAt(t){const seg=sequence.find(s=>t<s.end)??sequence.at(-1);if(!seg)return {kcal:0,cents:0,p:A};const f=Math.max(0,Math.min(1,(t-seg.start)/(seg.end-seg.start))),rentalStart=sequence.find(s=>s.rental)?.start??Infinity,rentalEnd=sequence.filter(s=>s.rental).at(-1)?.end??Infinity,rental=Math.max(0,Math.min(t,rentalEnd)-rentalStart);const cents=t>=rentalStart?(fare(Math.max(.001,rental),current.settings.profile,current.settings.newPass).total):0;return {kcal:seg.k0+(seg.k1-seg.k0)*f,cents,p:[seg.p0[0]+(seg.p1[0]-seg.p0[0])*f,seg.p0[1]+(seg.p1[1]-seg.p0[1])*f]};}
function drawChart(){const chart=$('chart');chart.replaceChildren();if(!current){chart.append(el('text',{x:500,y:85,'text-anchor':'middle',fill:'#8a948c','font-size':14},'경로를 계산하면 이동시간에 따른 누적값이 나타납니다.'));return;}const max=metric==='kcal'?current.kcal:current.fare.total/100,margin=35,width=930,height=115,total=current.totalSeconds||1;for(let i=0;i<=3;i++){const y=135-i*height/3;chart.append(el('line',{x1:margin,x2:985,y1:y,y2:y,stroke:'#e6eadf','stroke-dasharray':'3 4'}),el('text',{x:0,y:y+3,fill:'#9aa58f','font-size':10},(max*i/3).toFixed(metric==='usd'?2:0)));}let pts=[];const times=new Set([0,total,...sequence.flatMap(s=>[s.start,s.end])]);if(metric==='usd'){const rstart=sequence.find(s=>s.rental)?.start;if(rstart!==undefined){times.add(Math.max(0,rstart-.0001));times.add(rstart);for(let i=0;i<=current.fare.minutes;i++){const t=rstart+i*60;if(t<=total){times.add(t);times.add(Math.min(total,t+.0001));}}}}else for(let i=0;i<=100;i++)times.add(total*i/100);for(const t of [...times].sort((a,b)=>a-b)){const val=valueAt(t),v=metric==='kcal'?val.kcal:val.cents/100;pts.push([margin+t/total*width,135-(max?v/max:0)*height]);}const d=pts.map((p,i)=>(i?'L':'M')+p.join(',')).join(' '),color=metric==='kcal'?'#7e9e5f':'#b98d59';chart.append(el('path',{d:d+` L${margin+width},135 L${margin},135 Z`,fill:metric==='kcal'?'#edf3e3':'#f5eee3'}),el('path',{d,stroke:color,'stroke-width':2,fill:'none'}),el('line',{id:'playhead',x1:margin,x2:margin,y1:10,y2:137,stroke:'#365d44','stroke-width':1}));for(let i=0;i<=4;i++)chart.append(el('text',{x:margin+i*width/4,y:157,'text-anchor':'middle',fill:'#9aa58f','font-size':10},mins(total*i/4)+'분'));}
function updatePlayback(){if(!current)return;const val=valueAt(playAt);$('clock').textContent=clock(playAt)+' / '+clock(current.totalSeconds);$('scrubber').value=current.totalSeconds?playAt/current.totalSeconds*1000:0;$('currentCost').textContent='누적 '+(metric==='kcal'?Math.round(val.kcal)+' kcal':money(val.cents)+' USD');const x=35+(current.totalSeconds?playAt/current.totalSeconds:0)*930;const ph=$('playhead');if(ph){ph.setAttribute('x1',x);ph.setAttribute('x2',x);}const q=xy(val.p);$('mapTraveler').replaceChildren(el('circle',{cx:q[0],cy:q[1],r:29,fill:'#fcfef5',stroke:'#385d46','stroke-width':10}));}
let lastFrame=0;function frame(now){if(playing&&current){playAt=Math.min(current.totalSeconds,playAt+Math.min((now-lastFrame)/1000,.2)*Number($('playSpeed').value));updatePlayback();if(playAt>=current.totalSeconds){playing=false;$('play').textContent='▶ 다시 재생';}}lastFrame=now;requestAnimationFrame(frame);}requestAnimationFrame(frame);
function download(name,value,type='application/json'){const url=URL.createObjectURL(new Blob([typeof value==='string'?value:JSON.stringify(value)],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export').onclick=async()=>{if(!result)return;const manifest={...stateData.manifest,exported:new Date().toISOString(),osm_sha256:await hashJSON(raw),boundary_sha256:await hashJSON(stateData.geometry)};const rows=['elapsed_seconds,gross_kcal,pre_tax_usd'];for(let t=0;t<current.totalSeconds;t+=10){const v=valueAt(t);rows.push(`${t},${v.kcal.toFixed(3)},${(v.cents/100).toFixed(2)}`);}const v=valueAt(current.totalSeconds);rows.push(`${current.totalSeconds},${v.kcal.toFixed(3)},${(v.cents/100).toFixed(2)}`);const blob=zipFiles({'result.json':{schema:'cp-distance-1',a:unproject(A),b:unproject(B),settings:settings(),result,manifest},'route.geojson':{type:'FeatureCollection',features:current.legs.map(l=>l.geojson)},'cumulative.csv':rows.join('\n'),'snapshot.json':{schema:'cp-snapshot-1',...stateData,manifest,a:unproject(A),b:unproject(B),settings:settings()}});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='central-park-journey.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>40*1024*1024)throw new Error('파일은 40MB 이하여야 합니다.');const d=JSON.parse(await file.text());if(d.schema!=='cp-snapshot-1'||!d.geometry||!Array.isArray(d.raw?.elements)||!Array.isArray(d.stations))throw new Error('유효한 스냅샷 파일이 아닙니다.');if(d.manifest?.osm_sha256&&d.manifest.osm_sha256!==await hashJSON(d.raw))throw new Error('도로 데이터 해시가 일치하지 않습니다.');if(d.manifest?.boundary_sha256&&d.manifest.boundary_sha256!==await hashJSON(d.geometry))throw new Error('경계 데이터 해시가 일치하지 않습니다.');epoch++;clearInterval(stationTimer);area=makeArea(d.geometry);raw=d.raw;stations=d.stations;demo=false;imported=true;stateData=d; // Replay uses a fixed availability snapshot; original timestamps stay in manifest.
 const snapshotNow=Math.max(...stations.map(s=>s.timestamp).filter(Number.isFinite));for(const s of stations){s.recorded_timestamp=s.recorded_timestamp??s.timestamp;s.timestamp=Date.now()/1000-(snapshotNow-s.timestamp);}if(d.a)A=project(d.a);if(d.b)B=project(d.b);if(d.settings){for(const id of ['mass','speed','met','walkLimit','pause','profile'])if(d.settings[id]!==undefined)$(id).value=d.settings[id];$('newPass').checked=!!d.settings.newPass;}updateCoords();updateRate();$('modeBadge').classList.add('demo');$('modeBadge').innerHTML='<i></i> 저장된 시나리오 · 현재 상태 아님';$('mapSource').textContent='가져온 데이터 스냅샷 · '+(d.manifest?.exported??'시각 미상');clearResult();setupWorker(d);}catch(error){showError('가져오기 실패: '+error.message);}e.target.value='';};
function updateRate(){const p=POLICY.profiles[$('profile').value];$('rateNote').textContent=`잠금 해제 ${money(p.unlock)} + ${money(p.rate)} / 분`;$('newPass').disabled=$('profile').value!=='day';}
for(const name of ['A','B']){const sel=$('place'+name);places.forEach(([label],i)=>{const o=document.createElement('option');o.value=i;o.textContent=label;sel.append(o);});sel.value=name==='A'?0:7;sel.onchange=()=>{const p=places[Number(sel.value)][1];if(p)choosePoint(name,project(p));sel.value=String(places.findIndex(x=>x[1]&&distance(project(x[1]),name==='A'?A:B)<1));};$('coord'+name).onchange=()=>{const ll=$('coord'+name).value.split(',').map(s=>Number(s.trim()));if(ll.length!==2||!ll.every(Number.isFinite)||Math.abs(ll[0])>180||Math.abs(ll[1])>90){showError('INVALID_COORDINATE');return;}choosePoint(name,project(ll));};$('pick'+name).onclick=()=>{selected=name;for(const n of ['A','B']){$('pick'+n).classList.toggle('active',name===n);$('pick'+n).setAttribute('aria-pressed',String(name===n));}};}
$('swap').onclick=()=>{[A,B]=[B,A];[$('placeA').value,$('placeB').value]=[$('placeB').value,$('placeA').value];updateCoords();drawMarkers();schedule();};$('profile').onchange=()=>{updateRate();schedule();};for(const id of ['mass','speed','met','walkLimit','pause','newPass'])$(id).onchange=schedule;$('calculate').onclick=calculate;$('retry').onclick=()=>connect(false,true);$('example').onclick=useExample;$('refresh').onclick=()=>built?refreshStations():connect();$('compare').onchange=drawRoutes;
for(const btn of document.querySelectorAll('[data-metric]'))btn.onclick=()=>{metric=btn.dataset.metric;document.querySelectorAll('[data-metric]').forEach(b=>b.classList.toggle('selected',b===btn));$('chartUnit').textContent=metric==='kcal'?'에너지':'요금';drawRoutes();drawChart();updatePlayback();};
$('play').onclick=()=>{if(!current)return;if(playAt>=current.totalSeconds)playAt=0;playing=!playing;$('play').textContent=playing?'Ⅱ 일시정지':'▶ 재생';};$('reset').onclick=()=>{playing=false;playAt=0;$('play').textContent='▶ 재생';updatePlayback();};$('scrubber').oninput=()=>{playing=false;$('play').textContent='▶ 재생';playAt=Number($('scrubber').value)/1000*(current?.totalSeconds??0);updatePlayback();};$('aboutButton').onclick=()=>$('about').showModal();$('closeAbout').onclick=()=>$('about').close();$('about').onclick=e=>{if(e.target===$('about')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
const screenPoint=e=>{const p=$('map').createSVGPoint();p.x=e.clientX;p.y=e.clientY;const q=p.matrixTransform($('map').getScreenCTM().inverse());return [q.x,q.y];};let drag=null;
$('map').onpointerdown=e=>{if(e.button!==0)return;const marker=e.target.closest('[data-point]');drag={name:marker?.getAttribute('data-point'),start:screenPoint(e),client:[e.clientX,e.clientY],station:e.target.closest('[data-station]')?.getAttribute('data-station'),view:[...view],moved:false};$('map').setPointerCapture(e.pointerId);};
$('map').onpointermove=e=>{if(!drag)return;drag.moved ||=Math.hypot(e.clientX-drag.client[0],e.clientY-drag.client[1])>4;if(drag.name){const p=world(screenPoint(e));if(area.contains(p)){if(drag.name==='A')A=p;else B=p;drawMarkers();updateCoords();}}else if(drag.moved){const dx=(e.clientX-drag.client[0])/$('map').getBoundingClientRect().width*drag.view[2],dy=(e.clientY-drag.client[1])/$('map').getBoundingClientRect().height*drag.view[3];view=[drag.view[0]-dx,drag.view[1]-dy,drag.view[2],drag.view[3]];setView();}};
$('map').onpointerup=e=>{if(!drag)return;const d=drag;drag=null;if(d.name){$('place'+d.name).value=String(places.length-1);schedule();}else if(!d.moved){const station=d.station;if(station){const s=stations.find(s=>s.id===station);choosePoint(selected,s.p);}else choosePoint(selected,world(screenPoint(e)));}};$('map').onpointercancel=()=>drag=null;
$('map').onkeydown=e=>{const m=e.target.closest('[data-point]');if(!m)return;const dirs={ArrowLeft:[-10,0],ArrowRight:[10,0],ArrowUp:[0,10],ArrowDown:[0,-10]};if(dirs[e.key]){e.preventDefault();const name=m.getAttribute('data-point'),p=name==='A'?A:B;choosePoint(name,[p[0]+dirs[e.key][0],p[1]+dirs[e.key][1]]);document.querySelector('[data-point="'+name+'"]').focus();}};
function zoom(factor,center){const c=center??[view[0]+view[2]/2,view[1]+view[3]/2],w=Math.max(baseView[2]/10,Math.min(baseView[2]*2,view[2]*factor)),h=w*baseView[3]/baseView[2],fx=(c[0]-view[0])/view[2],fy=(c[1]-view[1])/view[3];view=[c[0]-w*fx,c[1]-h*fy,w,h];setView();}$('map').addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1.12:.89,screenPoint(e));},{passive:false});$('zoomIn').onclick=()=>zoom(.8);$('zoomOut').onclick=()=>zoom(1.25);$('fit').onclick=fit;
window.addEventListener('beforeunload',()=>{worker?.terminate();clearInterval(stationTimer);});updateCoords();updateRate();drawBase();connect();
